package com.andye.warmod.radar.display.client;
import com.andye.warmod.block.RadarDisplayPanelBlock; import com.andye.warmod.block.entity.RadarDisplayPanelBlockEntity; import com.andye.warmod.radar.display.RadarDisplayOfflineReason; import com.andye.warmod.radar.display.RadarDisplaySnapshot; import com.andye.warmod.radar.station.RadarSweepMath; import com.mojang.blaze3d.vertex.PoseStack; import java.util.ArrayList; import java.util.List; import net.minecraft.client.renderer.SubmitNodeCollector; import net.minecraft.client.renderer.blockentity.BlockEntityRenderer; import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider; import net.minecraft.client.renderer.feature.ModelFeatureRenderer; import net.minecraft.client.renderer.state.level.CameraRenderState; import net.minecraft.resources.Identifier; import net.minecraft.world.phys.Vec3; import org.jspecify.annotations.Nullable;
public final class RadarDisplayBlockEntityRenderer implements BlockEntityRenderer<RadarDisplayPanelBlockEntity,RadarDisplayRenderState>{public RadarDisplayBlockEntityRenderer(BlockEntityRendererProvider.Context context){}@Override public RadarDisplayRenderState createRenderState(){return new RadarDisplayRenderState();}@Override public void extractRenderState(RadarDisplayPanelBlockEntity display,RadarDisplayRenderState state,float partialTick,Vec3 camera,ModelFeatureRenderer.@Nullable CrumblingOverlay overlay){BlockEntityRenderer.super.extractRenderState(display,state,partialTick,camera,overlay);state.structureValid=display.valid();state.width=Math.max(1,display.width());state.height=Math.max(1,display.height());state.tileX=display.tileX();state.tileY=display.tileY();state.controller=display.controller();state.displayId=display.displayId();state.facing=display.getBlockState().getValue(RadarDisplayPanelBlock.FACING);state.online=false;state.syncing=display.link()!=null;state.offlineReason=display.link()==null?RadarDisplayOfflineReason.UNLINKED:RadarDisplayOfflineReason.STATION_MISSING;state.observations=List.of();if(display.getLevel()==null||state.displayId==null)return;Identifier dimension=display.getLevel().dimension().identifier();double clientTime=display.getLevel().getGameTime()+partialTick;ClientRadarDisplayState.View view=ClientRadarDisplayState.INSTANCE.view(dimension,state.controller,state.displayId,clientTime);if(view==null)return;RadarDisplaySnapshot snapshot=view.snapshot();state.structureValid=snapshot.structureValid();state.online=snapshot.online();state.syncing=false;state.stale=view.stale();state.offlineReason=snapshot.offlineReason();state.width=Math.max(1,snapshot.width());state.height=Math.max(1,snapshot.height());state.horizontalRadius=snapshot.horizontalRadius();state.verticalRadius=snapshot.verticalRadius();state.warningRadius=snapshot.warningRadius();state.fireRadius=snapshot.fireRadius();state.redstoneSignal=snapshot.redstoneSignal();state.serverNow=view.serverNow();state.sweepPeriod=snapshot.sweepPeriodTicks();state.sweepAngleDegrees=RadarSweepMath.angleDegrees(state.serverNow,snapshot.phaseOffset());if(snapshot.radarCentre()!=null)state.radarCentre=Vec3.atCenterOf(snapshot.radarCentre());List<RadarDisplayRenderObservation> observations=new ArrayList<>();for(var observation:snapshot.observations()){RadarDisplayRenderObservation rendered=RadarDisplayRenderObservation.from(observation,state.serverNow,state.sweepPeriod);if(rendered.alpha()>0)observations.add(rendered);}state.observations=List.copyOf(observations);}@Override public void submit(RadarDisplayRenderState state,PoseStack pose,SubmitNodeCollector collector,CameraRenderState camera){if(!state.structureValid||state.width<1||state.height<1||state.tileX<0||state.tileX>=state.width||state.tileY<0||state.tileY>=state.height)return;collector.submitCustomGeometry(pose,RadarDisplayRenderPipelines.SCREEN,(p,b)->RadarDisplayMapRenderer.renderTile(p,b,state));}@Override public int getViewDistance(){return 320;}@Override public boolean shouldRenderOffScreen(){return true;}}